package com.example.starter.batch.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;

/**
 * 登记包装标签计划请求。plannedQuantity 为计划包装数量（件）；
 * 标签号段按左闭右开 [labelStart, labelEnd) 解释，labelEnd 必须大于 labelStart。
 */
public record RegisterLabelPlanRequest(
        @jakarta.validation.constraints.NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotNull(message = "plannedQuantity 不能为空")
        @Min(value = 1, message = "plannedQuantity 必须为正整数") Integer plannedQuantity,
        @NotNull(message = "labelStart 不能为空") Long labelStart,
        @NotNull(message = "labelEnd 不能为空") Long labelEnd
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 标签计划响应。号段按左闭右开 [labelStart, labelEnd) 解释。
 */
public record LabelPlanResponse(
        String batchKey,
        int plannedQuantity,
        long labelStart,
        long labelEnd,
        Instant createdAt
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 批量封箱请求。一次提交 1～50 条封箱记录，先校验完整最终集合，
 * 任一标签失败整次回滚，不留下部分占用。
 */
public record SealCasesRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotNull(message = "cases 不能为空")
        @Size(min = 1, max = 50, message = "cases 必须包含 1～50 条封箱记录")
        List<@Valid CaseSpec> cases
) {

    /**
     * 单条封箱规格：caseKey 批次内唯一；labelNo 须落在批次号段内且全局未占用；
     * quantity 为正整数（件）。
     */
    public record CaseSpec(
            @NotBlank(message = "caseKey 不能为空") String caseKey,
            @NotNull(message = "labelNo 不能为空") Long labelNo,
            @NotNull(message = "quantity 不能为空")
            @Min(value = 1, message = "quantity 必须为正整数") Integer quantity
    ) {
    }
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 单条封箱记录响应。status 为 ACTIVE/VOIDED；voidedAt 与 voidReason 未作废时为 null。
 */
public record CaseResponse(
        String batchKey,
        String caseKey,
        long labelNo,
        int quantity,
        String status,
        int version,
        Instant createdAt,
        Instant voidedAt,
        String voidReason
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;
import java.util.List;

/**
 * 批量封箱响应。totalSealedQuantity 为当前有效封箱数量之和（件）；
 * plannedQuantity 为计划数量；remainingQuantity 为差额（计划 - 已封）。
 */
public record SealCasesResponse(
        String batchKey,
        List<CaseResponse> cases,
        int totalSealedQuantity,
        int plannedQuantity,
        int remainingQuantity,
        Instant sealedAt
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 封箱作废请求。reason 为作废原因，非空；仅未放行批次允许作废。
 */
public record VoidCaseRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "reason 不能为空") String reason
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 封箱作废响应。releasedQuantity 为本次作废释放的封箱数量（件）；
