public StoredResponse sealCases(String batchKey, SealCasesRequest req) {
    List<CaseSpec> specs = req.cases();
    // request-level duplicate checks (before tx, cheap)
    // duplicates of caseKey / labelNo within request -> 409
    fingerprint over batchKey + each spec (caseKey, labelNo, quantity)
    return executeIdempotent(CMD_SEAL, req.commandKey(), fingerprint, () -> {
        batch = findBatchForUpdate or 404
        status check: REJECTED/RELEASED/RECALLED/SPLIT -> 409
        plan = repo.findLabelPlan(batchKey).orElseThrow(422 "尚未登记标签计划")
        activeCases = repo.findActivePackCases(batchKey)
        existingCaseKeys = active + voided case keys (all pack_cases)
        usedLabels = repo.findUsedLabels(batchKey) set
        // validate complete final set
        for spec: 
            if labelNo < start || >= end -> 422 out of range
            if usedLabels.contains(labelNo) -> 409 duplicate
            if existingCaseKeys.contains(caseKey) -> 409
        newTotal = sumActive + sum(spec quantities)
        if newTotal > planned -> 422 with actual/required/excess
        // writes
        now; for each spec: insertPackCase(ACTIVE, version 1), insertLabelUsage
        remaining = planned - newTotal
        body = SealCasesResponse(...)
        return 201
    });
}
