    /**
     * 让批次走完 检验 PASS + 双角色批准 进入 RELEASED（含放行标签门禁与快照固化）。
     */
    private void releaseBatch(String batchKey) throws Exception {
        submitTestPass(batchKey);
        approve(batchKey, "qa-" + unique(), "QUALITY", "CK-AQ-" + unique(), 201);
